//! Winslow Pico firmware: scans buttons, rotary encoders and pots and reports them
//! to the PocketBeagle over UART, in the format defined by
//! `winslow-protocol`.
//!
//! Everything runs in one loop on a 500 µs timer. Polling at a fixed rate
//! (rather than an interrupt per pin) makes debouncing and encoder decoding
//! simple and deterministic, and is plenty for hand-operated controls.

#![no_std]
// `#[cfg(dt = ...)]` values are generated by the build, so rustc can't know them.
#![allow(unexpected_cfgs)]

extern crate alloc;

mod board;
mod link;

use alloc::vec::Vec;

use log::{error, info};
use winslow_protocol::{Message, VERSION};
use winslow_scan::{Debouncer, Quadrature, Smoother};
use zephyr::time::Duration;
use zephyr::timer::StoppedTimer;
use zephyr_panic as _;

use crate::board::{Input, Pots};
use crate::link::Link;

const SCAN_PERIOD_US: u32 = 500;
/// A button must hold a new level this many scans (5 ms) to count.
const DEBOUNCE_SAMPLES: u8 = 10;
/// Pots are read every this many scans (2 ms); they don't need more.
const POT_SCANS: u32 = 4;
/// Smallest pot change reported, in raw 12-bit codes (~0.2% of travel).
const POT_DEADBAND: u16 = 8;
/// Scans between heartbeats (500 ms).
const HEARTBEAT_SCANS: u32 = 1000;

#[unsafe(no_mangle)]
extern "C" fn rust_main() {
    // SAFETY: called once at startup, before anything else logs.
    unsafe {
        zephyr::set_logger().unwrap();
    }
    if let Err(e) = run() {
        error!("stopped: {e}");
    }
}

struct Button {
    input: Input,
    debouncer: Debouncer,
}

struct Encoder {
    a: Input,
    b: Input,
    decoder: Quadrature,
}

fn run() -> Result<(), &'static str> {
    let mut link = Link::new(board::link_uart())?;

    let mut buttons = board::buttons()
        .iter()
        .map(|spec| {
            Ok(Button {
                input: Input::new(spec)?,
                debouncer: Debouncer::new(),
            })
        })
        .collect::<Result<Vec<_>, &str>>()?;

    let mut encoders = board::encoders()
        .iter()
        .map(|e| {
            let a = Input::new(&e.a)?;
            let b = Input::new(&e.b)?;
            // Assumes the encoder is resting on a detent at power-up.
            let decoder = Quadrature::new(a.read(), b.read(), e.steps_per_detent as u8);
            Ok(Encoder { a, b, decoder })
        })
        .collect::<Result<Vec<_>, &str>>()?;

    let pots = Pots::new()?;
    let mut smoothers: Vec<Smoother> = (0..pots.len())
        .map(|_| Smoother::new(Pots::MAX, POT_DEADBAND))
        .collect();

    info!("{} pots", pots.len());
    for (i, b) in buttons.iter().enumerate() {
        info!("button {i}: GP{}", b.input.pin());
    }
    for (i, e) in encoders.iter().enumerate() {
        info!("encoder {i}: A GP{}, B GP{}", e.a.pin(), e.b.pin());
    }

    let mut led = led::Led::new();
    link.send(Message::Hello { version: VERSION });

    let period = Duration::micros(SCAN_PERIOD_US.into());
    let mut timer = StoppedTimer::new().start_simple(period, period);
    let mut scans = 0u32;

    loop {
        // Blocks until the next period. If we ever overran, this returns at
        // once and we simply carry on; nothing needs catching up.
        timer.read_count_wait();

        for (i, b) in buttons.iter_mut().enumerate() {
            match b.debouncer.update(b.input.read(), DEBOUNCE_SAMPLES) {
                Some(true) => link.send(Message::ButtonDown(i as u8)),
                Some(false) => link.send(Message::ButtonUp(i as u8)),
                None => {}
            }
        }

        for (i, e) in encoders.iter_mut().enumerate() {
            let delta = e.decoder.update(e.a.read(), e.b.read());
            if delta != 0 {
                link.send(Message::Encoder {
                    index: i as u8,
                    delta,
                });
            }
        }

        if scans.is_multiple_of(POT_SCANS) {
            for (i, smoother) in smoothers.iter_mut().enumerate() {
                if let Some(value) = pots.read(i).and_then(|raw| smoother.update(raw)) {
                    link.send(analog(i, value));
                }
            }
        }

        // The PocketBeagle asks for a sync when its daemon starts, since it
        // will usually have missed our hello (Linux boots much slower).
        while let Some(message) = link.receive() {
            if message == Message::Sync {
                link.send(Message::Hello { version: VERSION });
                for (i, b) in buttons.iter().enumerate() {
                    if b.debouncer.pressed() {
                        link.send(Message::ButtonDown(i as u8));
                    }
                }
                for (i, smoother) in smoothers.iter().enumerate() {
                    if let Some(value) = smoother.value() {
                        link.send(analog(i, value));
                    }
                }
            }
        }

        scans += 1;
        if scans == HEARTBEAT_SCANS {
            scans = 0;
            link.send(Message::Heartbeat);
            led.toggle();
        }
    }
}

/// A pot message, scaled from 12 to the protocol's 14 bits (4095 -> 16383).
fn analog(index: usize, value: u16) -> Message {
    Message::Analog {
        index: index as u8,
        value: value << 2 | value >> 10,
    }
}

/// The on-board LED blinks with the heartbeat, to show the firmware is alive.
mod led {
    #[cfg(dt = "aliases::led0")]
    pub struct Led(Option<zephyr::device::gpio::GpioPin>);

    #[cfg(dt = "aliases::led0")]
    impl Led {
        pub fn new() -> Self {
            let pin = zephyr::devicetree::aliases::led0::get_instance()
                .filter(|pin| pin.is_ready())
                .map(|mut pin| {
                    pin.configure(zephyr::raw::ZR_GPIO_OUTPUT_ACTIVE);
                    pin
                });
            Self(pin)
        }

        pub fn toggle(&mut self) {
            if let Some(pin) = &mut self.0 {
                pin.toggle_pin();
            }
        }
    }

    #[cfg(not(dt = "aliases::led0"))]
    pub struct Led;

    #[cfg(not(dt = "aliases::led0"))]
    impl Led {
        pub fn new() -> Self {
            Self
        }

        pub fn toggle(&mut self) {}
    }
}
